export default function next({ messages, previous, statusCode }) {
  const i = previous?.index ?? 0;
  if (previous && (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300))
    throw Error("Outlook update was not confirmed");
  if (i >= messages.length)
    return { state: { index: i }, more: false, id: "-", message: {}, contactFormula: "FALSE()" };
  const m = messages[i],
    email = m?.from?.emailAddress?.address;
  if (typeof m.id !== "string" || typeof email !== "string")
    throw Error("Missing Outlook message identity");
  return {
    state: { index: i + 1 },
    more: true,
    id: m.id,
    message: m,
    contactFormula: "{Email}='" + email.replace(/\\/g, "\\\\").replace(/'/g, "\\'") + "'",
  };
}

