export default function prepare({ message, contacts, categories, deletes }) {
  const names = categories.map((x) => x.fields?.Name).filter((x) => typeof x === "string" && x);
  if (!names.length) throw Error("Configure category Name records");
  return { prompt: JSON.stringify({ email: message, contacts, categories, deletes }), names };
}

