export default function prepare({ messageId, answer, names }) {
  if (!names.includes(answer.category)) throw Error("Model returned an unknown category");
  if (answer.subCategory && answer.subCategory !== "Action") throw Error("Invalid subcategory");
  return {
    endpoint: "/me/messages/" + encodeURIComponent(messageId),
    body: { categories: [answer.category] },
    action: answer.subCategory === "Action",
  };
}

