export default function collect({ previous, items, cursor }) {
  const all = [...(previous?.items ?? []), ...(items ?? [])];
  return {
    state: { items: all },
    items: all,
    more: typeof cursor === "string" && cursor.length > 0,
    cursor: cursor ?? null,
  };
}

