export default function next({ items, previous, statusCode, groupId }) {
  let i = previous?.index ?? 0;
  if (previous && (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300))
    throw Error("Airtable upsert not confirmed");
  while (i < items.length && items[i].group?.id !== groupId) i++;
  if (i >= items.length) return { state: { index: i }, more: false, body: { records: [] } };
  const x = items[i],
    email = x.column_values?.[6]?.text,
    type = x.column_values?.[1]?.text;
  if (typeof email !== "string" || !email.trim() || typeof x.name !== "string")
    throw Error("Missing contact name or email");
  const parts = x.name.trim().split(/\s+/);
  return {
    state: { index: i + 1 },
    more: true,
    body: {
      performUpsert: { fieldsToMergeOn: ["Email"] },
      records: [
        {
          fields: {
            Email: email,
            "First Name": parts[0],
            "Last Name": parts[1] ?? parts[0],
            Type: type ?? "",
          },
        },
      ],
    },
  };
}
